function renderHeader(){
  document.getElementById("site-header").innerHTML = `<div class="site-header"><div class="container nav-wrap"><a class="brand" href="${href("home")}"><strong>Dr. John Ughulu</strong><span>The Morale Booster</span></a><button class="menu-btn" aria-expanded="false" aria-controls="main-nav">Menu</button><nav class="nav" id="main-nav" aria-label="Primary">${nav.map(([id,label])=>`<a class="${PAGE_ID===id?"active":""}" href="${href(id)}">${label}</a>`).join("")}</nav></div></div>`;
  const btn=document.querySelector(".menu-btn"), menu=document.querySelector(".nav"); btn.addEventListener("click",()=>{const open=menu.classList.toggle("open");btn.setAttribute("aria-expanded",String(open))});
}
