const pages = {
home:()=>`<section class="hero"><div class="container hero-grid"><div><div class="eyebrow">Faith · Leadership · Purpose</div><h1>Lead with clarity.<br><span>Live with purpose.</span></h1><p class="hero-copy">Dr. John Ughulu is an author, public speaker, leadership strategist, scholar-practitioner, and Minister of the Gospel of Christ helping people discover, develop, and deploy their God-given potential.</p><div class="actions"><a class="btn btn-primary" href="${href("about")}">Discover His Story</a><a class="btn btn-secondary" href="${href("speaking")}">Invite Dr. Ughulu</a><a class="btn btn-secondary" href="${base}downloads/JohnUghulu_Website_Brochure.pdf" download>Download Website Brochure (PDF)</a></div></div>${portrait}</div></section><section class="stats"><div class="stat"><strong>8</strong><span>Published Books</span></div><div class="stat"><strong>15</strong><span>Research Publications</span></div><div class="stat"><strong>200+</strong><span>Podcast Episodes</span></div><div class="stat"><strong>1B+</strong><span>Lives in the Vision</span></div></section><section class="section"><div class="container"><div class="section-head"><div class="eyebrow">A multidimensional calling</div><h2>Ideas that move people and institutions forward</h2><p class="lead">At the intersection of faith, leadership, education, and entrepreneurship, Dr. Ughulu equips people to translate potential into meaningful impact.</p></div><div class="grid-3"><article class="card"><div class="icon">01</div><h3>Leadership Strategy</h3><p>Practical frameworks for ethical influence, organizational growth, succession, and resilient leadership.</p></article><article class="card"><div class="icon">02</div><h3>Purpose & Faith</h3><p>Christ-centered teaching that strengthens faith and helps people live with conviction, clarity, and service.</p></article><article class="card"><div class="icon">03</div><h3>Scholarship & Enterprise</h3><p>Research and education focused on entrepreneurship, artificial intelligence, governance, and sustainable development.</p></article></div></div></section><section class="section section-soft"><div class="container bio-layout">${portrait}<div class="content"><div class="eyebrow">Meet Dr. John Ughulu</div><h2>The Morale Booster</h2><p class="lead">A best-selling author and award-winning leadership strategist committed to fostering faith, cultivating leaders, and advancing purpose-driven enterprise.</p><p>Dr. Ughulu serves as Founder and President of Mainseed Christian University, Founder and Lead Servant of The Morale Booster Ministries, and host of The Morale Booster Podcast.</p><div class="actions"><a class="btn btn-dark" href="${href("about")}">Read Full Biography</a><a class="btn btn-outline" href="${href("organizations")}">Explore Organizations</a><a class="btn btn-outline" href="${base}downloads/JohnUghulu-Website-Brochure.pdf" download>Download Website Brochure (PDF)</a></div></div></div></section><section class="cta-band"><div class="container cta-flex"><h2>Bring a clear, purpose-centered voice to your next gathering.</h2><a class="btn btn-dark" href="${href("contact")}">Start a Conversation</a></div></section>`,
about:()=>`${hero("About","A life devoted to purpose, leadership, and service","Dr. John Ughulu brings scholarship, enterprise, ministry, and media together in one mission: helping people discover, develop, and deploy their God-given potential.")}<section class="section"><div class="container bio-layout">${portrait}<div class="prose content"><h2>Biography</h2><p>Known as “The Morale Booster,” Dr. John Ughulu is a best-selling author, award-winning leadership strategist, scholar-practitioner, ordained Minister of the Gospel, and public speaker based in Atlanta, Georgia.</p><p>He is the Founder and President of Mainseed Christian University, Founder and Lead Servant of The Morale Booster Ministries, Inc., and host of The Morale Booster Podcast. Through education, Christian ministry, publishing, coaching, and public dialogue, he develops principled leaders prepared to serve organizations, build enterprises, strengthen communities, and advance Christian ministry.</p><p>Dr. Ughulu holds a Ph.D. and M.A. in Christian Entrepreneurship and a B.S. in Computer Science. His continuing professional development includes a Global Fellowship in Comparative Law, a Harvard Business School Online Leadership Principles Certificate, and certification as a Les Brown Speaker and Trainer.</p><blockquote class="quote">His vision is to help one billion or more people discover, develop, and deploy their God-given potential through faith, leadership, and education by December 31, 2041.</blockquote></div></div></section><section class="section section-soft"><div class="container"><div class="section-head"><div class="eyebrow">Credentials & experience</div><h2>Scholarship grounded in practice</h2></div><div class="grid-3"><div class="card"><h3>Education</h3><p>Ph.D. and M.A. in Christian Entrepreneurship<br>B.S. in Computer Science</p></div><div class="card"><h3>Leadership Development</h3><p>Harvard Business School Online Leadership Principles Certificate and Certified Les Brown Speaker and Trainer.</p></div><div class="card"><h3>Research</h3><p>Several publications exploring leadership, entrepreneurship, artificial intelligence, governance, and workplace well-being.</p></div></div></div></section>`,
books:()=>`${hero("Books","Books for purposeful living and principled leadership","Search Dr. John Ughulu’s published works by title, subject, keyword, category, or year, then continue securely to Amazon.")}<section class="section"><div class="container"><div class="notice">All proceeds from Dr. John Ughulu’s book sales support the work and mission of The Morale Booster Ministries.</div>${libraryUI("books")}<div class="library-grid" id="library-grid"></div></div></section>`,
articles:()=>`${hero("Articles and peer-reviewed papers","Ideas, insights, and scholarly research","Browse Dr. John Ughulu’s original articles separately from his peer-reviewed papers and ResearchGate publications.")}<section class="section"><div class="container"><div class="collection-tabs" role="tablist" aria-label="Publication collections"><button class="collection-tab active" type="button" data-collection="articles" role="tab" aria-selected="true">Original Articles</button><button class="collection-tab" type="button" data-collection="papers" role="tab" aria-selected="false">Peer-Reviewed Papers</button></div><div class="collection-intro" id="collection-intro"></div>${libraryUI("publications")}<div class="library-grid" id="library-grid" aria-live="polite"></div></div></section>`,
speaking:()=>`${hero("Speaking & leadership","Ideas that clarify vision and activate purpose","Invite Dr. John Ughulu for keynotes, leadership development, moderated conversations, workshops, and faith-centered gatherings.")}<section class="section"><div class="container"><div class="section-head"><div class="eyebrow">Speaking themes</div><h2>Practical insight with moral clarity</h2></div><div class="grid-3"><article class="card"><h3>Purpose-Driven Leadership</h3><p>Helping leaders align identity, responsibility, vision, and service.</p></article><article class="card"><h3>Ethical Influence</h3><p>Building trust, integrity, accountability, and sustainable organizational culture.</p></article><article class="card"><h3>Entrepreneurship & Wealth Creation</h3><p>Developing enterprises that create value, opportunity, jobs, and lasting impact.</p></article><article class="card"><h3>Leadership in an AI-Driven World</h3><p>Preparing human-centered leaders for rapid technological and institutional change.</p></article><article class="card"><h3>From Shyness to Public Speaking</h3><p>Growing the confidence and communication skill to speak with authenticity.</p></article><article class="card"><h3>Faith, Calling & Service</h3><p>Equipping believers to lead through spiritual maturity and Christ-centered purpose.</p></article></div></div></section><section class="section section-dark"><div class="container cta-flex"><div><span class="pill">Available for selected engagements</span><h2>Invite Dr. Ughulu to speak</h2><p class="lead">Share your audience, date, location, format, and desired outcomes.</p></div><div class="actions"><a class="btn btn-primary" href="${href("speaker-intake")}">Complete Speaker Intake Form</a><a class="btn btn-secondary" href="${href("contact")}">Ask a Question</a></div></div></section>`,
"speaker-intake":()=>`${hero("Speaker intake form","Invite Dr. John Ughulu to your event","Share the details Dr. Ughulu and The Morale Booster team need to understand your audience, program goals, logistics, and technical requirements.")}<section class="section"><div class="container intake-layout"><div class="intake-intro"><div class="eyebrow">Event planning</div><h2>Tell us about your engagement</h2><p>Complete the sections below as fully as you can. Fields marked required must be completed before submission. The team will review your request and follow up using the contact information provided.</p><p><strong>This form is an inquiry and does not confirm a booking.</strong></p><p>For questions before submitting, email <a href="mailto:info@johnughulu.com">info@johnughulu.com</a>.</p></div><form id="speaker-intake-form" class="card intake-form"><section class="intake-section"><h2>1 Contact information</h2><div class="form-grid"><div class="field"><label for="intake-name">Contact name *</label><input id="intake-name" name="contact_name" required maxlength="120" autocomplete="name"></div><div class="field"><label for="intake-org">Organization or company *</label><input id="intake-org" name="organization" required maxlength="180" autocomplete="organization"></div><div class="field"><label for="intake-email">Email address *</label><input id="intake-email" name="email" type="email" required maxlength="254" autocomplete="email"></div><div class="field"><label for="intake-phone">Phone number *</label><input id="intake-phone" name="phone" type="tel" required maxlength="40" autocomplete="tel"></div><div class="field"><label for="intake-title">Role or title</label><input id="intake-title" name="contact_title" maxlength="120" autocomplete="organization-title"></div><div class="field"><label for="intake-website">Organization website</label><input id="intake-website" name="organization_website" type="url" maxlength="300" placeholder="https://"></div><div class="field field-wide"><label for="intake-referral">How did you hear about Dr. Ughulu?</label><input id="intake-referral" name="referral_source" maxlength="250"></div></div></section><section class="intake-section"><h2>2 Program overview</h2><div class="form-grid"><div class="field"><label for="intake-event">Event or meeting name *</label><input id="intake-event" name="event_name" required maxlength="200"></div><div class="field"><label for="intake-date">Event date *</label><input id="intake-date" name="event_date" type="date" required></div><div class="field"><label for="intake-start">Program start time</label><input id="intake-start" name="start_time" type="time"></div><div class="field"><label for="intake-end">Program end time</label><input id="intake-end" name="end_time" type="time"></div><div class="field"><label for="intake-format">Event format *</label><select id="intake-format" name="event_format" required><option value="">Select one</option><option>In person</option><option>Virtual</option><option>Hybrid</option></select></div><div class="field"><label for="intake-size">Estimated audience size *</label><input id="intake-size" name="audience_size" type="number" min="1" max="1000000" required></div><div class="field field-wide"><label for="intake-venue">Venue name and full address or virtual platform *</label><textarea id="intake-venue" name="venue" required maxlength="800"></textarea></div><div class="field"><label for="intake-topic">Requested topic or theme *</label><input id="intake-topic" name="topic" required maxlength="250"></div><div class="field"><label for="intake-duration">Requested presentation length</label><input id="intake-duration" name="presentation_length" maxlength="80" placeholder="For example 45 minutes"></div><div class="field"><label for="intake-qa">Q and A time</label><input id="intake-qa" name="qa_length" maxlength="80" placeholder="For example 15 minutes"></div><div class="field"><label for="intake-budget">Estimated budget in USD</label><input id="intake-budget" name="budget" maxlength="100" inputmode="decimal"></div><div class="field field-wide"><label for="intake-summary">Event summary *</label><textarea id="intake-summary" name="event_summary" required maxlength="2000" placeholder="Describe the event, the larger program, and Dr. Ughulu's expected role."></textarea></div></div></section><section class="intake-section"><h2>3 Audience and outcomes</h2><div class="form-grid"><div class="field field-wide"><label for="intake-audience">Describe the target audience *</label><textarea id="intake-audience" name="audience_profile" required maxlength="2000" placeholder="Include professions, age range, experience level, and relevant cultural or faith context."></textarea></div><div class="field field-wide"><label for="intake-objectives">What should participants know, feel, or do after the presentation? *</label><textarea id="intake-objectives" name="objectives" required maxlength="2000" placeholder="List up to three goals or outcomes."></textarea></div><div class="field field-wide"><label for="intake-context">Other speakers, program theme, requested content, or continuing education requirements</label><textarea id="intake-context" name="program_context" maxlength="2000"></textarea></div><div class="field field-wide"><label for="intake-sensitive">Sensitive topics, terminology to avoid, accessibility needs, or accommodations</label><textarea id="intake-sensitive" name="special_considerations" maxlength="2000"></textarea></div></div></section><section class="intake-section"><h2>4 Promotion and media</h2><div class="form-grid"><div class="field field-wide"><label for="intake-promotion">How will the presentation be promoted, and what materials do you need from the speaker?</label><textarea id="intake-promotion" name="promotion_plan" maxlength="1800"></textarea></div><div class="field"><label for="intake-recording">Will the presentation be recorded? *</label><select id="intake-recording" name="recording_plan" required><option value="">Select one</option><option>No</option><option>Audio only</option><option>Video</option><option>Livestream</option><option>To be determined</option></select></div><div class="field"><label for="intake-recording-rights">Proposed recording use and rights</label><input id="intake-recording-rights" name="recording_rights" maxlength="300"></div><div class="field field-wide check-group"><span class="field-label">Permissions requested</span><label class="check"><input type="checkbox" name="permission_social"><span>Dr. Ughulu may identify the organization, event, and venue in his social media.</span></label><label class="check"><input type="checkbox" name="permission_leads"><span>Dr. Ughulu may invite participants to voluntarily share contact information.</span></label><label class="check"><input type="checkbox" name="permission_sales"><span>A table may be provided for books, materials, or displays.</span></label></div></div></section><section class="intake-section"><h2>5 Travel and event-day logistics</h2><div class="form-grid"><div class="field"><label for="intake-travel">Travel required *</label><select id="intake-travel" name="travel_required" required><option value="">Select one</option><option>No</option><option>Yes - driving</option><option>Yes - flying</option><option>To be determined</option></select></div><div class="field"><label for="intake-travel-owner">Who will arrange travel?</label><input id="intake-travel-owner" name="travel_arrangements" maxlength="200"></div><div class="field"><label for="intake-day-name">Event-day contact name *</label><input id="intake-day-name" name="event_day_contact" required maxlength="120"></div><div class="field"><label for="intake-day-phone">Event-day contact phone *</label><input id="intake-day-phone" name="event_day_phone" type="tel" required maxlength="40"></div><div class="field field-wide"><label for="intake-arrival">Arrival, parking, building access, security, unloading, and preparation-room instructions</label><textarea id="intake-arrival" name="arrival_logistics" maxlength="2000"></textarea></div></div></section><section class="intake-section"><h2>6 Technical and room requirements</h2><div class="form-grid"><div class="field field-wide checkbox-grid"><span class="field-label">Equipment available</span><label class="check"><input type="checkbox" name="equipment" value="Wireless lavaliere microphone"><span>Wireless lavaliere microphone</span></label><label class="check"><input type="checkbox" name="equipment" value="Handheld microphone"><span>Handheld microphone</span></label><label class="check"><input type="checkbox" name="equipment" value="Lectern"><span>Lectern</span></label><label class="check"><input type="checkbox" name="equipment" value="Projector and screen"><span>Projector and screen</span></label><label class="check"><input type="checkbox" name="equipment" value="Presentation laptop connection"><span>Presentation laptop connection</span></label><label class="check"><input type="checkbox" name="equipment" value="Internet access"><span>Internet access</span></label><label class="check"><input type="checkbox" name="equipment" value="Flip chart and markers"><span>Flip chart and markers</span></label><label class="check"><input type="checkbox" name="equipment" value="A/V technician"><span>A/V technician</span></label></div><div class="field"><label for="intake-room">Room arrangement</label><select id="intake-room" name="room_arrangement"><option value="">Select one</option><option>Theater</option><option>Classroom</option><option>Banquet rounds</option><option>U shape</option><option>Virtual</option><option>Other</option></select></div><div class="field"><label for="intake-stage">Stage arrangement</label><select id="intake-stage" name="stage_arrangement"><option value="">Select one</option><option>Raised stage</option><option>Audience level</option><option>Not applicable</option><option>To be determined</option></select></div><div class="field field-wide"><label for="intake-tech-notes">Setup time, A/V contact, internet credentials process, handouts, room notes, or other requirements</label><textarea id="intake-tech-notes" name="technical_notes" maxlength="2000"></textarea></div></div></section><section class="intake-section"><h2>7 Final details and consent</h2><div class="field"><label for="intake-notes">Additional notes</label><textarea id="intake-notes" name="additional_notes" maxlength="2500"></textarea></div><label class="check"><input type="checkbox" name="privacy_consent" required><span>I consent to the collection and use of the information in this form to evaluate and respond to this speaking inquiry and maintain a related record, as described in the <a href="${href("privacy")}" target="_blank" rel="noopener">Privacy Policy <span class="sr-only">(opens in a new tab)</span></a>. <strong>Required.</strong></span></label><label class="check"><input type="checkbox" name="marketing_consent"><span>I would also like to receive newsletters and promotional messages. This is optional and is not required to submit an inquiry.</span></label><p class="form-status" id="intake-status" role="status" aria-live="polite"></p><button class="btn btn-dark" type="submit">Submit Speaking Inquiry</button></section></form></div></section>`,
ministry:()=>`${hero("Ministry","Christ-centered service that strengthens faith and purpose","The Morale Booster Ministries is a non-denominational Christian ministry helping people grow in Christ, live with purpose, and serve with courage.")}<section class="section"><div class="container grid-2"><div class="content"><div class="eyebrow">Minister of the Gospel of Christ</div><h2>Faith that moves into service</h2><p>As Founder and Lead Servant, Dr. John Ughulu teaches the Gospel of Christ and develops believers through worship, prayer, biblical teaching, leadership formation, and community outreach.</p><p>The ministry’s rhythm includes Sunday Live Worship, Mindset Monday, Wisdom Wednesday, and FaithFuel Friday, creating consistent spaces for spiritual growth and practical application.</p><a class="btn btn-dark" href="https://themoralebooster.com" target="_blank" rel="noopener">Visit The Morale Booster Ministries</a></div><div class="card"><h3>Gather. Grow. Go.</h3><p><strong>Gather</strong> in Christ-centered community.</p><p><strong>Grow</strong> through Scripture, prayer, discipleship, and leadership.</p><p><strong>Go</strong> into the world to serve, encourage, and make a meaningful difference.</p></div></div></section><section class="section section-soft"><div class="container"><div class="section-head"><h2>Weekly ministry experiences</h2></div><div class="grid-3"><div class="card"><h3>Sunday Live Worship</h3><p>Worship and Word every Sunday.</p></div><div class="card"><h3>Wisdom Wednesday</h3><p>In-depth Bible study centered on Christ.</p></div><div class="card"><h3>FaithFuel Friday</h3><p>Prayer, faith, encouragement, and spiritual renewal.</p></div></div></div></section>`,
organizations:()=>`${hero("Organizations & media","Building institutions that equip people to lead and serve","Dr. John Ughulu’s work extends through education, ministry, enterprise, publishing, and media.")}<section class="section"><div class="container"><div class="grid-2"><a class="card logo-card entity-card" href="https://mainseeduniversity.com" target="_blank" rel="noopener noreferrer" aria-label="Visit Mainseed Christian University website"><div class="eyebrow">Education</div><h3>Mainseed Christian University</h3><p>Developing Christ-centered leaders equipped to lead organizations, build enterprises, serve communities, and advance Christian ministry.</p><span class="entity-link">Visit website →</span></a><a class="card logo-card entity-card" href="https://themoralebooster.com" target="_blank" rel="noopener noreferrer" aria-label="Visit The Morale Booster Ministries website"><div class="eyebrow">Christian Ministry</div><h3>The Morale Booster Ministries</h3><p>A non-denominational ministry devoted to the Gospel of Christ, discipleship, prayer, leadership, and outreach.</p><span class="entity-link">Visit website →</span></a><a class="card logo-card entity-card" href="https://newgigz.com" target="_blank" rel="noopener noreferrer" aria-label="Visit NEWGIGZ Inc. website"><div class="eyebrow">Enterprise and Media</div><h3>NEWGIGZ Inc.</h3><p>A platform supporting enterprise, digital media, publishing, innovation, and purpose-driven ideas.</p><span class="entity-link">Visit website →</span></a><a class="card logo-card entity-card" href="https://www.youtube.com/@themoralebooster/streams" target="_blank" rel="noopener noreferrer" aria-label="Visit The Morale Booster Podcast on YouTube"><div class="eyebrow">Podcast</div><h3>The Morale Booster Podcast</h3><p>Leadership conversations, practical encouragement, interviews, and insights that help people discover and develop their potential.</p><span class="entity-link">Watch on YouTube →</span><span class="entity-link spotify-link" role="link" tabindex="0" data-spotify="https://open.spotify.com/show/1DVXcevW6fhHCE1B8z3NmB?si=f9b7203a9ba14bc2&amp;nd=1&amp;dlsi=2a03cb0d9dfa4da2">Listen on Spotify →</span></a></div></div></section><section class="section section-dark"><div class="container"><div class="section-head"><div class="eyebrow">Media reach</div><h2>Conversations that travel</h2><p class="lead">Dr. Ughulu’s work has been featured across FOX, CBS, NBC, HSBN, and WATC, extending leadership and purpose-centered ideas to wider audiences.</p></div></div></section>`,
contact:()=>`${hero("Contact","Start a meaningful conversation","For speaking, interviews, leadership development, ministry, education, or partnership inquiries, share the details below.")}<section class="section"><div class="container grid-2"><form class="card form-card" id="contact-form"><h2>Contact Dr. Ughulu</h2><div class="field"><label for="contact-name">Name</label><input id="contact-name" name="name" autocomplete="name" required maxlength="120"></div><div class="field"><label for="contact-email">Email</label><input id="contact-email" name="email" type="email" autocomplete="email" required maxlength="254"></div><div class="field"><label for="contact-subject">Subject</label><input id="contact-subject" name="subject" required maxlength="160"></div><div class="field"><label for="contact-message">Message</label><textarea id="contact-message" name="message" required maxlength="4000"></textarea></div><button class="btn btn-dark" type="submit">Send Inquiry</button><p class="form-status" id="contact-status" role="status"></p></form><aside><div class="eyebrow">Areas of inquiry</div><h2>How may we help?</h2><p>Speaking engagements</p><p>Leadership workshops and consulting</p><p>Media and podcast interviews</p><p>Ministry collaboration</p><p>Academic and research engagement</p><p>Organizational partnerships</p><p><strong>Atlanta, Georgia, United States</strong></p></aside></div></section>`,
privacy:()=>`${hero("Privacy","Privacy Policy","This policy explains how visitor information is collected, used, protected, and managed when accessing Dr. John Ughulu’s resources.")}<section class="section"><div class="container prose legal"><p><strong>Effective date: September 14, 2026</strong></p><h2>Information we collect</h2><p>When you choose to continue to a book on Amazon or a publication on ResearchGate, we collect your name, email address, the selected resource, the destination provider, your required privacy consent, any optional marketing consent, the applicable consent notice version, and the submission date. Contact inquiries may include your name, email, subject, and message.</p><h2>Why we collect it</h2><p>We use this information to provide the requested resource redirect, maintain a record of consent, understand interest in Dr. Ughulu’s work, respond to inquiries, protect the website, and comply with applicable obligations. We send newsletters or promotional messages only when you separately choose to receive them.</p><h2>Marketing choice</h2><p>Marketing consent is optional and is not required to access Amazon or ResearchGate resources. You may withdraw marketing consent at any time using the unsubscribe method in a message or by contacting us.</p><h2>Service providers and external websites</h2><p>Data is stored using a secured database service with access controls. When you continue to Amazon or ResearchGate, their respective privacy practices apply. We do not control those external websites.</p><h2>Retention and security</h2><p>We retain personal information only as long as reasonably necessary for the purposes described in this policy, consent records, legal obligations, and legitimate operational needs. We use reasonable administrative and technical safeguards, but no internet transmission or storage system can be guaranteed completely secure.</p><h2>Your choices and rights</h2><p>Depending on where you live, you may request access, correction, deletion, or restriction of personal information, or withdraw consent. Submit a request through the <a href="${href("contact")}">Contact page</a> or email <span data-privacy-email>info@johnughulu.com</span>. We may need to verify your identity before completing a request.</p><h2>Children’s privacy</h2><p>This resource-access feature is not directed to children under 13, and we do not knowingly collect their information through it.</p><h2>Policy updates</h2><p>We may update this policy when practices or requirements change. The effective date above identifies the current version.</p><h2>Contact</h2><p>Privacy questions may be submitted through the <a href="${href("contact")}">Contact page</a> or to <span data-privacy-email>info@johnughulu.com</span>.</p></div></section>`,
accessibility:()=>`${hero("Accessibility","Accessibility Statement","JohnUghulu.com is committed to providing an inclusive digital experience for people with disabilities.")}<section class="section"><div class="container prose legal"><p><strong>Last updated: October 7, 2026</strong></p><h2>Our commitment</h2><p>JohnUghulu.com is committed to making its website content and digital experiences accessible to the broadest possible audience, including people who use assistive technologies.</p><h2>Accessibility standard</h2><p>Our accessibility work uses the Web Content Accessibility Guidelines (WCAG) 2.2 Level AA as an engineering target. Accessibility is an ongoing process, and conformance cannot be guaranteed solely by automated testing.</p><h2>Measures we take</h2><p>We use semantic page structure, keyboard-accessible navigation and controls, visible focus indicators, text alternatives for meaningful images, labeled forms, responsive layouts, reduced-motion support, status announcements for dynamic interactions, and accessibility checks when website features are changed.</p><h2>Third-party content</h2><p>Some links lead to third-party services such as Amazon, ResearchGate, social media platforms, and other external websites. We do not control the accessibility of those external services.</p><h2>Feedback and assistance</h2><div class="accessibility-contact"><p>If you experience an accessibility barrier or need information from this website in another format, please contact us through the <a href="${href("contact")}">Contact page</a> or email <span data-privacy-email>info@johnughulu.com</span>. Please identify the page or feature involved and describe the assistance you need.</p></div><h2>Continuous improvement</h2><p>We will continue reviewing the website as content and technology change and will address confirmed accessibility barriers as practicable.</p></div></section>`
};

function libraryUI(type){return `<div class="filters" data-type="${type}"><input id="search" type="search" placeholder="Search title, subject, keyword, category, or year" aria-label="Search library"><select id="category" aria-label="Filter by category"><option value="">All categories</option></select><select id="subject" aria-label="Filter by subject"><option value="">All subjects</option></select><select id="year" aria-label="Filter by year"><option value="">All years</option></select></div>`}
function setupLibrary(items,provider){
  const grid=document.getElementById("library-grid"), search=document.getElementById("search"), cat=document.getElementById("category"), subj=document.getElementById("subject"), year=document.getElementById("year");
  search.value="";cat.innerHTML='<option value="">All categories</option>';subj.innerHTML='<option value="">All subjects</option>';year.innerHTML='<option value="">All years</option>';
  const fill=(el,values)=>[...new Set(values.filter(Boolean))].sort().forEach(v=>el.insertAdjacentHTML("beforeend",`<option value="${escapeHtml(v)}">${escapeHtml(v)}</option>`)); fill(cat,items.map(x=>x.category));fill(subj,items.map(x=>x.subject));fill(year,items.map(x=>x.year).sort().reverse());
  const render=()=>{const q=search.value.trim().toLowerCase();const shown=items.filter(x=>(!q||`${x.title} ${x.subject} ${x.keywords} ${x.category} ${x.year}`.toLowerCase().includes(q))&&(!cat.value||x.category===cat.value)&&(!subj.value||x.subject===subj.value)&&(!year.value||x.year===year.value));grid.innerHTML=shown.length?shown.map(x=>resourceCard(x,provider)).join(""):`<div class="empty">No resources match those filters.</div>`;grid.querySelectorAll("[data-resource]").forEach(btn=>btn.addEventListener("click",()=>openConsent(JSON.parse(btn.dataset.resource))))};[search,cat,subj,year].forEach(el=>el.oninput=render);render();
}
function resourceCard(item,provider){
  const data=escapeHtml(JSON.stringify({...item,provider,url:item.url||(provider==="Amazon"?AMAZON_URL:RESEARCHGATE_URL)}));
  const cover=provider==="Amazon"?`<div class="book-cover-wrap"><img class="book-cover" src="${escapeHtml(item.cover)}" alt="Cover of ${escapeHtml(item.title)}" loading="lazy"></div>`:"";
  const meta=`<div class="resource-meta"><span class="tag">${escapeHtml(item.category)}</span><span class="tag">${escapeHtml(item.subject)}</span>${item.year?`<span class="tag">${item.year}</span>`:""}</div>`;
  if(provider==="Article"){
    const published=item.date?new Date(`${item.date}T12:00:00`).toLocaleDateString("en-US",{year:"numeric",month:"long",day:"numeric"}):"";
    return `<article class="card resource-card article-card">${meta}${published?`<p class="article-date">Published ${escapeHtml(published)}</p>`:""}<h3>${escapeHtml(item.title)}</h3><p>${escapeHtml(item.excerpt||"Read this original article by Dr. John Ughulu.")}</p><a class="btn btn-dark" href="${href("articles")}${encodeURIComponent(item.id)}/">Read Article</a></article>`;
  }
  const description=provider==="Amazon"?"Available for purchase through Amazon. All proceeds support the work and mission of The Morale Booster Ministries.":"Peer-reviewed research and scholarly work. Continue to the ResearchGate profile to view availability.";
  return `<article class="card resource-card">${cover}${meta}<h3>${escapeHtml(item.title)}</h3><p>${description}</p><button class="btn btn-dark" data-resource="${data}">Continue to ${provider}</button></article>`;
}
async function setupArticlesPage(){
  const grid=document.getElementById("library-grid");
  try{
    const response=await fetch(`${base}articles.json`);
    if(!response.ok)throw new Error("Articles could not be loaded");
    const articles=(await response.json()).sort((a,b)=>String(b.date||"").localeCompare(String(a.date||"")));
    const articleId=window.ARTICLE_ID || new URLSearchParams(window.location.search).get("article");
    if(articleId){
      const article=articles.find(item=>item.id===articleId);
      if(!article){document.getElementById("main").innerHTML=`${hero("Article not found","This article is unavailable","Return to the article library to continue browsing.")}<section class="section"><div class="container"><a class="btn btn-dark" href="${href("articles")}">Back to Articles</a></div></section>`;return}
      renderArticle(article);return;
    }
    const intro=document.getElementById("collection-intro");
    const tabs=[...document.querySelectorAll("[data-collection]")];
    const show=collection=>{
      tabs.forEach(tab=>{const active=tab.dataset.collection===collection;tab.classList.toggle("active",active);tab.setAttribute("aria-selected",String(active))});
      if(collection==="articles"){intro.innerHTML=`<div><div class="eyebrow">Original articles</div><h2>Insights for life, leadership, faith, and enterprise</h2><p>Search and read ${articles.length} original articles directly on this website.</p></div>`;setupLibrary(articles,"Article")}
      else{intro.innerHTML='<div><div class="eyebrow">Peer-reviewed papers</div><h2>Research and scholarly publications</h2><p>These publications are separate from the original articles and are available through Dr. Ughulu’s ResearchGate profile.</p></div>';setupLibrary(papers,"ResearchGate")}
    };
    tabs.forEach(tab=>tab.addEventListener("click",()=>show(tab.dataset.collection)));show("articles");
  }catch(error){if(grid)grid.innerHTML='<div class="empty">The article library could not be loaded. Please refresh the page and try again.</div>'}
}
function renderArticle(article){
  document.title=`${article.title} | Dr. John Ughulu`;
  const date=article.date?new Date(`${article.date}T12:00:00`).toLocaleDateString("en-US",{year:"numeric",month:"long",day:"numeric"}):"";
  const blocks=article.blocks.map(block=>block.type==="heading"?`<h2>${escapeHtml(block.text)}</h2>`:`<p>${escapeHtml(block.text)}</p>`).join("");
  document.getElementById("main").innerHTML=`${hero("Original article",escapeHtml(article.title),"Articles and insights by Dr. John Ughulu")}<section class="section"><div class="container article-layout"><header class="article-byline"><span class="article-byline-author">By <strong>Dr. John Ughulu</strong></span>${date?`<span class="article-byline-separator" aria-hidden="true">·</span><time datetime="${escapeHtml(article.date)}">Published ${escapeHtml(date)}</time>`:""}</header><a class="back-link" href="${href("articles")}">← Back to Articles and Papers</a>${article.id==="public-disclaimer-clarification-and-notice-of-nonpartisanship"?`<figure class="article-headshot"><img src="${base}assets/dr-john-ughulu-headshot.png" alt="Dr. John Ughulu" loading="eager"></figure>`:""}<div class="resource-meta"><span class="tag">${escapeHtml(article.category)}</span><span class="tag">${escapeHtml(article.subject)}</span>${article.year?`<span class="tag">${article.year}</span>`:""}</div><div class="article-actions"><button class="btn btn-dark" id="download-article-pdf" type="button">Download Article as PDF</button><span class="download-note">PDF format only</span></div><article class="article-content">${blocks}</article></div></section>`;
  document.getElementById("download-article-pdf").addEventListener("click",()=>downloadArticlePdf(article));
}

function downloadArticlePdf(article){
  const replacements={"’":"'","‘":"'","“":"\"","”":"\"","–":"-","—":"-","•":"*","…":"..."};
  const clean=value=>String(value||"").normalize("NFKD").replace(/[^\x20-\x7E\n]/g,char=>replacements[char]||"");
  const escapePdf=value=>clean(value).replace(/\\/g,"\\\\").replace(/\(/g,"\\(").replace(/\)/g,"\\)");
  const wrap=(text,maxChars)=>{const lines=[];clean(text).split(/\n+/).forEach(paragraph=>{const words=paragraph.trim().split(/\s+/).filter(Boolean);if(!words.length){lines.push("");return}let line="";words.forEach(word=>{if(word.length>maxChars){if(line){lines.push(line);line=""}for(let i=0;i<word.length;i+=maxChars)lines.push(word.slice(i,i+maxChars));return}const next=line?`${line} ${word}`:word;if(next.length>maxChars){lines.push(line);line=word}else line=next});if(line)lines.push(line)});return lines};
  const pageWidth=612,pageHeight=792,margin=54,bottom=55;
  const pages=[];let commands=[],y=pageHeight-margin;
  const newPage=()=>{if(commands.length)pages.push(commands.join("\n"));commands=[];y=pageHeight-margin};
  const addLine=(text,size=11,bold=false,indent=0,leading=size*1.45)=>{if(y-leading<bottom)newPage();commands.push(`BT /${bold?"F2":"F1"} ${size} Tf ${margin+indent} ${y} Td (${escapePdf(text)}) Tj ET`);y-=leading};
  const addSpace=amount=>{if(y-amount<bottom)newPage();else y-=amount};
  const addWrapped=(text,size=11,bold=false,indent=0,after=7)=>{const max=Math.max(20,Math.floor((pageWidth-(margin*2)-indent)/(size*.52)));wrap(text,max).forEach(line=>addLine(line,size,bold,indent));addSpace(after)};
  addWrapped(article.title,20,true,0,10);
  addWrapped(`Dr. John Ughulu${article.date?` | Published ${article.date}`:""}`,10,false,0,16);
  (article.blocks||[]).forEach(block=>{if(block.type==="heading"){addSpace(7);addWrapped(block.text,14,true,0,7)}else addWrapped(block.text,11,false,0,8)});
  if(commands.length)pages.push(commands.join("\n"));
  const objects=[null];
  const addObject=body=>{objects.push(body);return objects.length-1};
  const fontRegular=addObject("<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>");
  const fontBold=addObject("<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold >>");
  const pagesObject=addObject("");
  const pageObjects=[];
  pages.forEach(content=>{const stream=addObject(`<< /Length ${content.length} >>\nstream\n${content}\nendstream`);pageObjects.push(addObject(`<< /Type /Page /Parent ${pagesObject} 0 R /MediaBox [0 0 ${pageWidth} ${pageHeight}] /Resources << /Font << /F1 ${fontRegular} 0 R /F2 ${fontBold} 0 R >> >> /Contents ${stream} 0 R >>`))});
  objects[pagesObject]=`<< /Type /Pages /Count ${pageObjects.length} /Kids [${pageObjects.map(id=>`${id} 0 R`).join(" ")}] >>`;
  const catalog=addObject(`<< /Type /Catalog /Pages ${pagesObject} 0 R >>`);
  let pdf="%PDF-1.4\n",offsets=[0];
  for(let i=1;i<objects.length;i++){offsets[i]=pdf.length;pdf+=`${i} 0 obj\n${objects[i]}\nendobj\n`}
  const xref=pdf.length;pdf+=`xref\n0 ${objects.length}\n0000000000 65535 f \n`;
  for(let i=1;i<objects.length;i++)pdf+=`${String(offsets[i]).padStart(10,"0")} 00000 n \n`;
  pdf+=`trailer\n<< /Size ${objects.length} /Root ${catalog} 0 R >>\nstartxref\n${xref}\n%%EOF`;
  const blob=new Blob([pdf],{type:"application/pdf"}),url=URL.createObjectURL(blob),link=document.createElement("a");
  link.href=url;link.download=`${String(article.id||article.title).replace(/[^a-z0-9]+/gi,"-").replace(/^-|-$/g,"").toLowerCase()||"article"}.pdf`;document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);
}
function escapeHtml(s){return String(s).replace(/[&<>"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]))}

function openConsent(resource){
  const saved=JSON.parse(localStorage.getItem("johnUghuluResourceConsent")||"null");
  if(saved?.name&&saved?.email&&saved?.privacy){recordResource(resource,{visitor_name:saved.name,email:saved.email,privacy_consent:true,marketing_consent:Boolean(saved.marketing)});return}
  const opener=document.activeElement;
  document.body.classList.add("modal-open");
  document.getElementById("consent-root").innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="consent-title" aria-describedby="consent-desc" tabindex="-1"><button class="menu-btn modal-close" id="modal-close" type="button" aria-label="Close resource access dialog">Close</button><div class="eyebrow">One-time visitor details</div><h2 id="consent-title">Continue to ${resource.provider}</h2><p id="consent-desc">You selected <strong>${escapeHtml(resource.title)}</strong>. Submit the required details below. You will be redirected only after the submission is securely recorded.</p><form id="resource-form"><div class="field"><label for="visitor-name">Name</label><input id="visitor-name" name="name" required maxlength="120" autocomplete="name"></div><div class="field"><label for="visitor-email">Email address</label><input id="visitor-email" name="email" type="email" required maxlength="254" autocomplete="email"></div><label class="check"><input type="checkbox" name="privacy" required><span>I consent to the collection and use of my information to provide this resource access and maintain a consent record, as described in the <a href="${href("privacy")}" target="_blank" rel="noopener">Privacy Policy <span class="sr-only">(opens in a new tab)</span></a>. <strong>Required.</strong></span></label><label class="check"><input type="checkbox" name="marketing"><span>I would also like to receive newsletters and promotional messages. Optional, and not required for access.</span></label><p class="form-status" id="resource-status" role="status" aria-live="polite"></p><div class="modal-actions"><button type="button" class="btn btn-outline" id="modal-cancel">Cancel</button><button type="submit" class="btn btn-dark">Continue to ${resource.provider}</button></div></form></section></div>`;
  const root=document.getElementById("consent-root"),dialog=root.querySelector(".modal");
  const close=()=>{document.body.classList.remove("modal-open");root.innerHTML="";if(opener&&opener.focus)opener.focus()};
  const focusables=()=>[...dialog.querySelectorAll('a[href],button:not([disabled]),input:not([disabled]),select:not([disabled]),textarea:not([disabled]),[tabindex]:not([tabindex="-1"])')];
  dialog.addEventListener("keydown",e=>{if(e.key==="Escape"){e.preventDefault();close();return}if(e.key==="Tab"){const f=focusables();if(!f.length)return;const first=f[0],last=f[f.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
  root.querySelector("#modal-close").onclick=close;root.querySelector("#modal-cancel").onclick=close;root.querySelector("#resource-form").onsubmit=e=>submitResource(e,resource);
  root.querySelector("#visitor-name").value=saved?.name||"";root.querySelector("#visitor-email").value=saved?.email||"";root.querySelector('[name="privacy"]').checked=Boolean(saved?.privacy);root.querySelector('[name="marketing"]').checked=Boolean(saved?.marketing);
  requestAnimationFrame(()=>root.querySelector("#modal-close").focus());
}
async function submitResource(event,resource){
  event.preventDefault();const form=event.currentTarget;await recordResource(resource,{visitor_name:form.elements.name.value.trim(),email:form.elements.email.value.trim().toLowerCase(),privacy_consent:form.elements.privacy.checked,marketing_consent:form.elements.marketing.checked},form);
}
async function recordResource(resource,visitor,form=null){
  const cfg=window.SITE_CONFIG||{},status=document.getElementById("resource-status"),btn=form?.querySelector("button[type=submit]");
  if(!cfg.supabaseUrl||!cfg.supabaseAnonKey){if(status)status.textContent="Secure resource access is being configured for the review preview. Please try again after launch setup is complete.";return}
  if(btn)btn.disabled=true;if(status)status.textContent="Recording your consent securely…";
  const payload={...visitor,resource_id:resource.id,resource_title:resource.title,resource_url:resource.url,provider:resource.provider,consent_version:"2026-09-14"};
  try{const res=await fetch(`${cfg.supabaseUrl}/rest/v1/resource_access`,{method:"POST",headers:{apikey:cfg.supabaseAnonKey,Authorization:`Bearer ${cfg.supabaseAnonKey}`,"Content-Type":"application/json",Prefer:"return=minimal"},body:JSON.stringify(payload)});if(!res.ok)throw new Error("Submission was not accepted");localStorage.setItem("johnUghuluResourceConsent",JSON.stringify({name:payload.visitor_name,email:payload.email,privacy:true,marketing:payload.marketing_consent}));window.location.assign(resource.url)}catch(err){if(status)status.textContent="We could not securely record your submission. Please try again.";if(btn)btn.disabled=false}
}
async function setupSpeakerIntake(){
  const form=document.getElementById("speaker-intake-form");if(!form)return;
  form.addEventListener("submit",async event=>{
    event.preventDefault();
    const cfg=window.SITE_CONFIG||{},status=document.getElementById("intake-status"),button=form.querySelector('button[type="submit"]');
    if(!cfg.supabaseUrl||!cfg.supabaseAnonKey){status.textContent="Secure form submission is not available yet. Please email info@johnughulu.com.";return}
    if(!form.reportValidity())return;
    button.disabled=true;status.textContent="Submitting your speaking inquiry securely...";
    const data=new FormData(form), equipment=data.getAll("equipment");
    const details={contact_title:data.get("contact_title")||"",organization_website:data.get("organization_website")||"",referral_source:data.get("referral_source")||"",start_time:data.get("start_time")||"",end_time:data.get("end_time")||"",event_format:data.get("event_format")||"",venue:data.get("venue")||"",presentation_length:data.get("presentation_length")||"",qa_length:data.get("qa_length")||"",budget:data.get("budget")||"",event_summary:data.get("event_summary")||"",audience_profile:data.get("audience_profile")||"",objectives:data.get("objectives")||"",program_context:data.get("program_context")||"",special_considerations:data.get("special_considerations")||"",promotion_plan:data.get("promotion_plan")||"",recording_plan:data.get("recording_plan")||"",recording_rights:data.get("recording_rights")||"",permission_social:data.has("permission_social"),permission_leads:data.has("permission_leads"),permission_sales:data.has("permission_sales"),travel_required:data.get("travel_required")||"",travel_arrangements:data.get("travel_arrangements")||"",event_day_contact:data.get("event_day_contact")||"",event_day_phone:data.get("event_day_phone")||"",arrival_logistics:data.get("arrival_logistics")||"",equipment,room_arrangement:data.get("room_arrangement")||"",stage_arrangement:data.get("stage_arrangement")||"",technical_notes:data.get("technical_notes")||"",additional_notes:data.get("additional_notes")||""};
    const payload={contact_name:String(data.get("contact_name")||"").trim(),organization:String(data.get("organization")||"").trim(),email:String(data.get("email")||"").trim().toLowerCase(),phone:String(data.get("phone")||"").trim(),event_name:String(data.get("event_name")||"").trim(),event_date:data.get("event_date"),topic:String(data.get("topic")||"").trim(),audience_size:Number(data.get("audience_size")),privacy_consent:data.has("privacy_consent"),marketing_consent:data.has("marketing_consent"),consent_version:"2026-10-15",details};
    try{const response=await fetch(`${cfg.supabaseUrl}/rest/v1/speaker_inquiries`,{method:"POST",headers:{apikey:cfg.supabaseAnonKey,Authorization:`Bearer ${cfg.supabaseAnonKey}`,"Content-Type":"application/json",Prefer:"return=minimal"},body:JSON.stringify(payload)});if(!response.ok)throw new Error("Submission was not accepted");form.reset();status.textContent="Thank you. Your speaking inquiry was submitted successfully. The Morale Booster team will review it and follow up.";status.focus()}catch(error){status.textContent="We could not securely submit your inquiry. Please try again or email info@johnughulu.com.";button.disabled=false}
  });
}
function setupContact(){const form=document.getElementById("contact-form");if(!form)return;form.addEventListener("submit",e=>{e.preventDefault();const subject=encodeURIComponent(form.elements.subject.value);const body=encodeURIComponent(`Name: ${form.elements.name.value}\nEmail: ${form.elements.email.value}\n\n${form.elements.message.value}`);window.location.href=`mailto:info@johnughulu.com?subject=${subject}&body=${body}`;document.getElementById("contact-status").textContent="Your email application has opened with this inquiry."})}

